import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import type { PocResult } from '../shared/types.js';

export interface VisualActionAdapter {
  tap(target: string): Promise<void>;
  input(target: string, value: string): Promise<void>;
  locate(target: string): Promise<{ x: number; y: number; confidence: number }>;
}

export class MockVisualActionAdapter implements VisualActionAdapter {
  history: string[] = [];
  async tap(target: string) { this.history.push(`tap:${target}`); }
  async input(target: string, value: string) { this.history.push(`input:${target}:${value}`); }
  async locate(target: string) { this.history.push(`locate:${target}`); return {x:500,y:320,confidence:0.99}; }
}

export async function resolveMidscenePackage(): Promise<string | null> {
  const require = createRequire(import.meta.url);
  for (const candidate of ['@midscene/web/playwright', '@midscene/web']) {
    try { return require.resolve(candidate); } catch {}
  }
  return null;
}

export async function loadMidsceneModule(): Promise<unknown | null> {
  const resolved = await resolveMidscenePackage();
  if (!resolved) return null;
  return import(pathToFileURL(resolved).href);
}

export function validateLiveConfig(env = process.env): string[] {
  const required = ['MIDSCENE_MODEL_BASE_URL','MIDSCENE_MODEL_API_KEY','MIDSCENE_MODEL_NAME','MIDSCENE_MODEL_FAMILY'];
  return required.filter(k => !env[k]);
}

export async function runPoc01(): Promise<PocResult> {
  const mock = new MockVisualActionAdapter();
  await mock.locate('确认转账按钮');
  await mock.input('转账金额', '100.00');
  await mock.tap('确认转账按钮');
  const packagePath = await resolveMidscenePackage();
  const missing = validateLiveConfig();
  const liveReady = Boolean(packagePath) && missing.length === 0;
  return {
    id: 'POC-01', name: '视觉模型与 Midscene 兼容性',
    status: liveReady ? 'PASS' : 'PARTIAL',
    checks: {
      adapterContract: mock.history.length === 3 ? 'PASS' : 'FAIL',
      instantActionMapping: mock.history[1] === 'input:转账金额:100.00' ? 'PASS' : 'FAIL',
      midscenePackage: packagePath ? 'PASS' : 'BLOCKED',
      liveModelConfig: missing.length === 0 ? 'PASS' : 'BLOCKED'
    },
    notes: [
      '已完成 VisualActionAdapter、Instant Action 映射和 Mock Smoke Test。',
      packagePath ? `检测到 Midscene: ${packagePath}` : '当前执行环境未安装 @midscene/web。',
      missing.length ? `真实模型联调缺少: ${missing.join(', ')}` : '真实模型配置已提供。',
      '公司环境需运行 scripts/run-poc01-live.ps1 完成真实视觉模型验收。'
    ],
    artifacts: ['src/poc01/midscene-compat.ts','scripts/run-poc01-live.ps1']
  };
}

