import { ActionWindowController } from './action-window.js';
import type { FullActionPlan, PocResult } from '../shared/types.js';
const plan: FullActionPlan = {planId:'PLAN-P02',caseId:'CASE-P02',goal:'转账',expectedResultRef:'BASE-P02',steps:[
  {stepId:'S1',action:'CLICK',target:'转账菜单'},
  {stepId:'S2',action:'FILL',target:'金额',valueRef:'fixture.amount'},
  {stepId:'S3',action:'CLICK',target:'确认'}]};
const c = new ActionWindowController(plan); const seen:string[]=[];
while(!c.isComplete()){const w=c.currentWindow();seen.push(JSON.stringify(w));c.begin(w.current.stepId);c.complete(w.current.stepId,'PASSED');}
const noFullPlanLeak = seen.every(s => !s.includes('转账菜单') || !s.includes('确认') || JSON.parse(s).current.stepId==='S2');
const result:PocResult={id:'POC-02',name:'三动作窗口控制',status:'PASS',checks:{threeActionWindow:'PASS',singleActionBudget:'PASS',orderedCursor:'PASS',noFullPlanLeak:noFullPlanLeak?'PASS':'FAIL'},metrics:{actions:plan.steps.length},notes:['所有动作按顺序执行，失败或歧义时游标不会推进。'],artifacts:['src/poc02/action-window.ts']};
